namespace RisingLands;
public static class RecruitmentTests {
    static void Check(bool value,string name){if(!value)throw new Exception("FAIL: "+name);Console.WriteLine("PASS: "+name);}
    public static void Run(string root){var visuals=new VisualCatalog();Simulation Create(){var w=LegacyAssets.Map(PackageLayout.Asset(root,"CD/WORLD/MONDE01.ETA"));visuals.Apply(w);for(int i=0;i<65536;i++)if(i!=5642&&Math.Abs((i&255)-10)+Math.Abs((i>>8)-22)<=6&&w.Objects[i] is 67 or >=29 and <=52){w.Objects[i]=0;w.Quantities[i]=0;}return new Simulation(w);}
        var sim=Create();var sanctuary=sim.World.Buildings.First(b=>b.Type==2);int originalCount=sim.World.Units.Count;Check(sim.Settlers(sanctuary.Slot)==8,"original sanctuary contains eight linked settlers");Check(sim.Recruit(5)&&sim.World.Resources[0]==26,"farmer training consumes original four-food cost");string before=sim.Serialize();Check(!sim.Recruit(7)&&sim.Serialize()==before,"occupied sanctuary rejects second training without charging");
        sim.Step();Check(sim.Recruitments[0].Progress==151,"training uses original occupancy-based progress increment");for(int i=0;i<80;i++)sim.Step();var copy=Create();copy.Restore(sim.Serialize());for(int i=0;i<600;i++){sim.Step();copy.Step();}
        Check(sim.Serialize()==copy.Serialize(),"training resumes deterministically after save/load");Check(sim.Recruitments[0].Finished&&sim.World.Units.Count==originalCount&&sim.World.Units.Count(u=>u.Type==5)==3&&sim.Settlers(sanctuary.Slot)==7,"completed farmer transforms exactly one housed settler");var farmer=sim.World.Units.First(u=>u.Slot==sim.Recruitments[0].SettlerSlot);Check(VisualCatalog.Visible(farmer)&&sim.Passable(farmer.X/1024,farmer.Y/1024)&&sim.Gather(farmer,5642),"trained farmer exits on free ground and can collect food");
        var loaded=Create();loaded.Restore(sim.Serialize());Check(loaded.World.Units.Count(u=>u.Type==5)==3,"trained role survives loading into fresh map");Check(sim.Recruit(7)&&sim.World.Resources[0]==20,"builder training consumes original six-food cost");for(int i=0;i<1200;i++)sim.Step();Check(sim.Recruitments.All(t=>t.Finished)&&sim.World.Units.Count(u=>u.Type==7)==2&&sim.Settlers(sanctuary.Slot)==6,"builder training consumes a different settler");
        var integrated=Create();var worker=integrated.World.Units.First(u=>u.Type==7);bool built=false;for(int y=8;y<22&&!built;y++)for(int x=20;x<29&&!built;x++)built=integrated.StartConstruction(worker,3,y*256+x);Check(built&&integrated.Recruit(5),"construction and recruitment can share the initial economy");for(int i=0;i<70;i++)integrated.Step();var resumed=Create();resumed.Restore(integrated.Serialize());for(int i=0;i<10000&&(!integrated.Complete(integrated.Constructions[0])||integrated.Recruitments.Any(t=>!t.Finished));i++){integrated.Step();resumed.Step();}Check(integrated.Complete(integrated.Constructions[0]),"hammer-paced warehouse finishes before assigning delivery");Check(integrated.Serialize()==resumed.Serialize(),"simultaneous construction and training survive save/load");var resident=integrated.ReleaseResident(integrated.World.Buildings.First(b=>b.Type==2).Slot);Check(resident!=null&&integrated.EnterBuilding(resident,integrated.Constructions[0].Id),"combined economy explicitly inhabits warehouse");for(int i=0;i<10000&&integrated.ResidentTrips.Count>0;i++)integrated.Step();var fresh=integrated.World.Units.First(u=>u.Slot==integrated.Recruitments[0].SettlerSlot);integrated.SetFoodDestination(fresh,2,integrated.Constructions[0].Id);integrated.Gather(fresh,5642);for(int i=0;i<20000&&fresh.FoodJob!=0;i++)integrated.Step();Check(integrated.World.Resources[0]==30&&integrated.World.Resources[4]==24,"complete build-train-collect cycle conserves initial funds and fourteen food");resumed.Restore(integrated.Serialize());Check(resumed.Serialize()==integrated.Serialize(),"finished combined economy restores exactly");
        string valid=sim.Serialize();var node=System.Text.Json.Nodes.JsonNode.Parse(valid)!;node["Recruitments"]![1]!["SettlerSlot"]=sim.Recruitments[0].SettlerSlot;string unchanged=loaded.Serialize();try{loaded.Restore(node.ToJsonString());throw new Exception("duplicate settler accepted");}catch(System.IO.InvalidDataException){}Check(loaded.Serialize()==unchanged,"duplicate settler in save rejected atomically");
    }
}
